-- Rend les corrections historiques indépendantes de la banque active.
-- Les tentatives existantes ont toutes été créées avec la version éditoriale 1.
alter table public.tage_mage_diagnostic_attempts
  add column if not exists question_snapshot jsonb;

alter table public.tage_mage_diagnostic_attempts
  add column if not exists submission_id uuid;

update public.tage_mage_diagnostic_attempts
set question_snapshot = '[{"id":"tm-comprehension-01","section":"comprehension","prompt":"Lisez : « Une ville qui réduit la place de la voiture ne supprime pas nécessairement la mobilité ; elle peut la redistribuer entre marche, vélo et transports collectifs. » Quelle idée est la mieux soutenue ?","options":["Réduire la voiture interdit tout déplacement.","La mobilité dépend exclusivement des transports collectifs.","La diminution de la voiture peut s’accompagner d’autres moyens de déplacement.","La marche et le vélo sont toujours plus rapides que la voiture.","Toutes les villes doivent interdire la voiture."],"correctIndex":2,"explanation":"Le texte oppose la place de la voiture à la mobilité et précise que celle-ci peut être redistribuée.","method":"Repérez la thèse exacte et écartez les réponses absolues ou ajoutant une recommandation.","difficulty":1,"estimatedSeconds":45,"contentVersion":1},{"id":"tm-comprehension-02","section":"comprehension","prompt":"Lisez : « Le télétravail peut réduire certains trajets, mais son bilan énergétique dépend aussi du chauffage des logements et de l’organisation des bureaux. » Quelle conclusion est justifiée ?","options":["Le télétravail diminue toujours la consommation d’énergie.","Le bilan énergétique du télétravail ne se limite pas aux trajets évités.","Les bureaux doivent être fermés.","Le chauffage des logements est négligeable.","Le télétravail augmente nécessairement les trajets."],"correctIndex":1,"explanation":"Le texte introduit deux autres facteurs énergétiques que les déplacements.","method":"Conservez les nuances : “peut” et “dépend aussi” excluent les conclusions catégoriques.","difficulty":2,"estimatedSeconds":50,"contentVersion":1},{"id":"tm-comprehension-03","section":"comprehension","prompt":"Lisez : « Un indicateur chiffré facilite la comparaison, sans pour autant épuiser la réalité qu’il mesure. » Que signifie “sans pour autant” ?","options":["L’indicateur rend toute comparaison impossible.","La comparaison est plus importante que la réalité.","L’indicateur décrit parfaitement la réalité.","L’utilité de comparaison n’implique pas une description complète.","La réalité ne peut jamais être mesurée."],"correctIndex":3,"explanation":"L’expression marque une concession : l’indicateur est utile, mais limité.","method":"Identifiez le lien logique entre les deux propositions plutôt que de surinterpréter le sujet.","difficulty":1,"estimatedSeconds":40,"contentVersion":1},{"id":"tm-comprehension-04","section":"comprehension","prompt":"Lisez : « La bibliothèque a étendu ses horaires le soir. La fréquentation a progressé, surtout chez les étudiants ; toutefois, cette hausse ne permet pas encore d’isoler l’effet propre des nouveaux horaires. » Pourquoi ?","options":["Les étudiants n’utilisent pas la bibliothèque le soir.","D’autres facteurs ont pu contribuer à la hausse.","Les horaires ont certainement causé toute la hausse.","La fréquentation a diminué chez les étudiants.","La bibliothèque ne collecte aucune donnée."],"correctIndex":1,"explanation":"Le mot “toutefois” signale qu’une corrélation observée ne prouve pas seule une causalité.","method":"Distinguez observation et explication causale ; cherchez l’option qui préserve cette prudence.","difficulty":3,"estimatedSeconds":55,"contentVersion":1},{"id":"tm-calcul-01","section":"calcul","prompt":"Un article coûte 80 €. Il bénéficie d’une remise de 15 %. Quel est son prix après remise ?","options":["62 €","65 €","68 €","72 €","74 €"],"correctIndex":2,"explanation":"15 % de 80 € vaut 12 €, donc le prix est 80 − 12 = 68 €.","method":"Calculez la remise puis soustrayez-la au prix initial.","difficulty":1,"estimatedSeconds":35,"contentVersion":1},{"id":"tm-calcul-02","section":"calcul","prompt":"Une équipe réalise 3/5 d’un dossier le lundi puis 1/4 du dossier total le mardi. Quelle fraction du dossier reste à réaliser ?","options":["1/10","3/20","1/5","1/4","7/20"],"correctIndex":1,"explanation":"La part réalisée est 3/5 + 1/4 = 12/20 + 5/20 = 17/20. Il reste 3/20.","method":"Mettez les fractions au même dénominateur avant de compléter à 1.","difficulty":2,"estimatedSeconds":50,"contentVersion":1},{"id":"tm-calcul-03","section":"calcul","prompt":"Un train parcourt 210 km en 2 h 30 min à vitesse constante. Quelle est sa vitesse moyenne ?","options":["72 km/h","80 km/h","84 km/h","90 km/h","105 km/h"],"correctIndex":2,"explanation":"2 h 30 min = 2,5 h, donc 210 ÷ 2,5 = 84 km/h.","method":"Convertissez d’abord les minutes en fraction d’heure, puis appliquez distance ÷ temps.","difficulty":2,"estimatedSeconds":45,"contentVersion":1},{"id":"tm-calcul-04","section":"calcul","prompt":"Le prix d’un abonnement augmente de 20 %, puis baisse de 20 % sur son nouveau prix. Par rapport au prix initial, il est :","options":["identique","en baisse de 4 %","en baisse de 2 %","en hausse de 4 %","en hausse de 2 %"],"correctIndex":1,"explanation":"En partant de 100, on obtient 120 puis 96 : le prix final est inférieur de 4 %.","method":"Testez avec une base de 100 : des pourcentages successifs ne s’annulent pas forcément.","difficulty":3,"estimatedSeconds":55,"contentVersion":1},{"id":"tm-conditions-minimales-01","section":"conditions_minimales","prompt":"x est-il positif ? (1) x² = 9. (2) x + 3 > 0.","options":["(1) seule suffit","(2) seule suffit","(1) et (2) ensemble suffisent, aucune seule ne suffit","Chaque affirmation seule suffit","Les deux affirmations ensemble ne suffisent pas"],"correctIndex":2,"explanation":"(1) donne x = −3 ou 3. (2) donne x > −3. Ensemble, x = 3 seulement.","method":"Testez chaque affirmation séparément, puis combinez-les sans résoudre plus que nécessaire.","difficulty":2,"estimatedSeconds":55,"contentVersion":1},{"id":"tm-conditions-minimales-02","section":"conditions_minimales","prompt":"Le nombre entier n est-il pair ? (1) n est divisible par 6. (2) n est divisible par 3.","options":["(1) seule suffit","(2) seule suffit","(1) et (2) ensemble suffisent, aucune seule ne suffit","Chaque affirmation seule suffit","Les deux affirmations ensemble ne suffisent pas"],"correctIndex":0,"explanation":"Tout multiple de 6 est pair, donc (1) répond oui. Un multiple de 3 peut être impair.","method":"Cherchez si une condition force une réponse unique, pas si elle apporte beaucoup d’informations.","difficulty":1,"estimatedSeconds":40,"contentVersion":1},{"id":"tm-conditions-minimales-03","section":"conditions_minimales","prompt":"Le rectangle a-t-il une aire supérieure à 30 cm² ? (1) Sa longueur est 8 cm. (2) Sa largeur est 4 cm.","options":["(1) seule suffit","(2) seule suffit","(1) et (2) ensemble suffisent, aucune seule ne suffit","Chaque affirmation seule suffit","Les deux affirmations ensemble ne suffisent pas"],"correctIndex":2,"explanation":"Chaque dimension isolée laisse l’autre inconnue. Ensemble, l’aire vaut 8 × 4 = 32 cm².","method":"Une aire exige les deux dimensions : vérifiez ensuite directement le seuil demandé.","difficulty":1,"estimatedSeconds":40,"contentVersion":1},{"id":"tm-conditions-minimales-04","section":"conditions_minimales","prompt":"La moyenne de a et b est-elle égale à 10 ? (1) a + b = 20. (2) a = b.","options":["(1) seule suffit","(2) seule suffit","(1) et (2) ensemble suffisent, aucune seule ne suffit","Chaque affirmation seule suffit","Les deux affirmations ensemble ne suffisent pas"],"correctIndex":0,"explanation":"La moyenne vaut (a + b) / 2 ; avec (1), elle vaut 20 / 2 = 10. (2) seul ne fixe aucune valeur.","method":"Traduisez la question en formule, puis voyez quelle donnée détermine cette formule.","difficulty":2,"estimatedSeconds":45,"contentVersion":1},{"id":"tm-expression-01","section":"expression","prompt":"Choisissez la phrase correctement rédigée.","options":["Les résultats qu’elle a obtenu sont encourageants.","Les résultats qu’elle a obtenus sont encourageants.","Les résultats qu’elle à obtenus sont encourageants.","Les résultat qu’elle a obtenus sont encourageant.","Les résultats qu’elle a obtenue sont encourageants."],"correctIndex":1,"explanation":"Le participe passé “obtenus” s’accorde avec le COD “résultats”, placé avant le verbe.","method":"Repérez le COD placé avant l’auxiliaire avoir, puis contrôlez pluriel et accents.","difficulty":1,"estimatedSeconds":40,"contentVersion":1},{"id":"tm-expression-02","section":"expression","prompt":"Quelle phrase exprime la relation logique la plus cohérente ?","options":["Le délai était court, pourtant nous avons remis le dossier à temps.","Le délai était court, donc nous avons remis le dossier à temps.","Le délai était court, car nous avons remis le dossier à temps.","Le délai était court, afin que nous avons remis le dossier à temps.","Le délai était court, néanmoins parce que nous avons remis le dossier à temps."],"correctIndex":0,"explanation":"“Pourtant” introduit correctement le contraste entre un délai court et une remise à temps.","method":"Identifiez d’abord le rapport : ici, le fait final contraste avec la difficulté annoncée.","difficulty":2,"estimatedSeconds":45,"contentVersion":1},{"id":"tm-expression-03","section":"expression","prompt":"Choisissez la formulation la plus précise et la moins redondante.","options":["Cette décision est une décision qui a été prise collectivement.","La décision collective a été prise par tous les membres collectivement.","Tous les membres ont pris collectivement la décision ensemble.","La décision a été prise collectivement.","La décision a été prise d’une manière collective par les membres."],"correctIndex":3,"explanation":"La quatrième proposition conserve l’information utile sans répéter “décision” ni “collectivement”.","method":"Supprimez les répétitions sans effacer le sens principal.","difficulty":1,"estimatedSeconds":35,"contentVersion":1},{"id":"tm-expression-04","section":"expression","prompt":"Complétez : « Ni le directeur ni les responsables ne ___ disponibles ce matin. »","options":["sera","seront","était","seraient","soit"],"correctIndex":1,"explanation":"Avec “ni… ni…” et un second sujet pluriel, le verbe se met ici au pluriel : “seront”.","method":"Repérez le noyau des sujets coordonnés et accordez le verbe au nombre approprié.","difficulty":2,"estimatedSeconds":45,"contentVersion":1},{"id":"tm-raisonnement-argumentation-01","section":"raisonnement_argumentation","prompt":"Argument : « Depuis que le campus a installé davantage d’arceaux, le nombre de vélos stationnés a augmenté. Les arceaux expliquent donc cette hausse. » Quelle information affaiblit le plus cette conclusion ?","options":["Les arceaux sont bleus.","Le campus a ouvert simultanément une nouvelle piste cyclable très fréquentée.","Certains étudiants préfèrent marcher.","Les arceaux sont situés près de la bibliothèque.","Le nombre de places de voiture est resté stable."],"correctIndex":1,"explanation":"La nouvelle piste constitue une cause alternative de l’augmentation observée.","method":"Pour affaiblir une causalité, cherchez un facteur concurrent apparu au même moment.","difficulty":2,"estimatedSeconds":55,"contentVersion":1},{"id":"tm-raisonnement-argumentation-02","section":"raisonnement_argumentation","prompt":"« Tous les stagiaires qui ont suivi la formation ont réussi le test final. Léa a réussi le test final. Donc Léa a suivi la formation. » Quel est le défaut ?","options":["La conclusion est nécessairement vraie.","Le raisonnement confond une condition suffisante avec une condition nécessaire.","La formation empêche de réussir.","Le test final n’a aucune utilité.","Léa ne peut pas être stagiaire."],"correctIndex":1,"explanation":"Réussir peut avoir d’autres causes ; “formation” implique “réussite”, non l’inverse.","method":"Schématisez A → B : observer B ne permet pas de conclure A.","difficulty":2,"estimatedSeconds":50,"contentVersion":1},{"id":"tm-raisonnement-argumentation-03","section":"raisonnement_argumentation","prompt":"Quelle donnée renforcerait le mieux l’affirmation « le nouveau tutorat améliore la réussite » ?","options":["Les tuteurs apprécient leur salle.","Après contrôle du niveau initial, les étudiants tutorés réussissent plus souvent que des étudiants comparables non tutorés.","Le tutorat coûte moins cher que prévu.","Les étudiants tutorés se connectent plus souvent à la plateforme.","Le programme porte un nouveau nom."],"correctIndex":1,"explanation":"La comparaison avec un groupe similaire, après contrôle du niveau initial, soutient directement un effet du tutorat.","method":"Privilégiez une preuve qui compare le résultat pertinent en limitant les facteurs de confusion.","difficulty":3,"estimatedSeconds":60,"contentVersion":1},{"id":"tm-raisonnement-argumentation-04","section":"raisonnement_argumentation","prompt":"« Cette application est fiable car elle a reçu cinq étoiles d’un utilisateur. » Quelle objection est la plus pertinente ?","options":["Les étoiles sont jaunes.","Un seul avis ne suffit pas à établir la fiabilité générale de l’application.","Les applications ne reçoivent jamais d’avis.","La fiabilité dépend uniquement du prix.","L’utilisateur a forcément tort."],"correctIndex":1,"explanation":"Un témoignage isolé est un échantillon trop faible pour une conclusion générale.","method":"Évaluez si la quantité et la représentativité des preuves correspondent à l’ampleur de la conclusion.","difficulty":1,"estimatedSeconds":40,"contentVersion":1},{"id":"tm-logique-01","section":"logique","prompt":"Trois dossiers A, B et C sont rangés de gauche à droite. A est à gauche de B et C est à droite de B. Quel est l’ordre ?","options":["A, B, C","A, C, B","B, A, C","B, C, A","C, A, B"],"correctIndex":0,"explanation":"Les deux contraintes imposent directement A avant B avant C.","method":"Placez d’abord l’élément central B, puis positionnez les deux autres par rapport à lui.","difficulty":1,"estimatedSeconds":35,"contentVersion":1},{"id":"tm-logique-02","section":"logique","prompt":"Dans un code de trois lettres, la lettre M est avant P et la lettre R est après P. Quelle proposition est forcément vraie ?","options":["R est avant M.","M est la dernière lettre.","P est avant R.","R est au milieu.","M et R sont adjacentes."],"correctIndex":2,"explanation":"La relation donnée M avant P avant R implique nécessairement P avant R.","method":"Chaînez les contraintes d’ordre et ne concluez que ce qui vaut dans tous les cas.","difficulty":1,"estimatedSeconds":40,"contentVersion":1},{"id":"tm-logique-03","section":"logique","prompt":"Quatre personnes, Ana, Bilal, Chloé et David, présentent chacune une fois. Ana passe avant Bilal. Chloé passe après David. Quelle séquence est possible ?","options":["Bilal, Ana, David, Chloé","David, Chloé, Bilal, Ana","Ana, Bilal, Chloé, David","David, Ana, Chloé, Bilal","Chloé, David, Ana, Bilal"],"correctIndex":3,"explanation":"La séquence D, A, C, B respecte Ana avant Bilal et David avant Chloé.","method":"Vérifiez chaque contrainte dans chaque proposition ; éliminez dès la première violation.","difficulty":2,"estimatedSeconds":50,"contentVersion":1},{"id":"tm-logique-04","section":"logique","prompt":"Un atelier a lieu mardi, mercredi ou jeudi. Il ne peut pas avoir lieu mardi si la salle B est réservée. La salle B est réservée mardi. Quel jour est impossible pour l’atelier ?","options":["Mardi","Mercredi","Jeudi","Mercredi ou jeudi","Aucun jour"],"correctIndex":0,"explanation":"Si B est réservée mardi, la condition exclut l’atelier ce jour-là.","method":"Appliquez une implication à son cas déclenché : B réservée mardi entraîne “pas mardi”.","difficulty":2,"estimatedSeconds":40,"contentVersion":1}]'::jsonb
where question_snapshot is null
  and content_version = 1;

update public.tage_mage_diagnostic_attempts
set submission_id = gen_random_uuid()
where submission_id is null;

-- Échoue volontairement si une version inconnue n'a pas pu être rétroalimentée.
alter table public.tage_mage_diagnostic_attempts
  alter column question_snapshot set not null;

alter table public.tage_mage_diagnostic_attempts
  alter column submission_id set not null;

create unique index if not exists tage_mage_attempts_user_submission_uidx
  on public.tage_mage_diagnostic_attempts (user_id, submission_id);

alter table public.tage_mage_diagnostic_attempts
  add constraint tage_mage_question_snapshot_is_array
  check (jsonb_typeof(question_snapshot) = 'array');
